const char msg_none[] = "";
const char msg_intro[] = "THE FIVE TEMPLES ARE SEALED\nAND THE ARTS FADE. ONLY YOU\nSTILL SEE THROUGH THE VEIL.\nA:CAST  B:STAFF  SELECT:ART";
const char msg_veilgate[] = "THE STONE TO THE NORTH IS A\nLIE. CAST VEIL, THEN WALK\nTHROUGH WHAT IS NOT THERE.";
const char msg_templegate[] = "THE EMBER TEMPLE. ITS SEAL\nWAITS BEYOND THE FLAME.";
const char msg_tome[] = "YOU LEARNED THE ART OF FIRE!\nBURN BRAMBLES AND LIGHT\nBRAZIERS. PRESS SELECT TO\nCHANGE YOUR ART.";
const char msg_trial[] = "TRIAL OF FLAME. DEFEAT ALL\nWHO WAIT HERE TO MASTER\nTHE ART.";
const char msg_sigil[] = "FIRE MASTERY II!\nYOUR FLAME BURNS HOTTER,\nCOSTS LESS, AND FLIES FAST.";
const char msg_heart[] = "A HEART VESSEL! YOUR LIFE\nGROWS STRONGER.";
const char msg_door[] = "SOMEWHERE NEARBY, A GREAT\nDOOR GRINDS OPEN.";
const char msg_seal[] = "THE EMBER SEAL IS BROKEN!\nTHE ART OF FIRE IS FREE,\nAND YOUR LIFE GROWS.";
const char msg_isle[] = "THE LAKE KEEPS A SECRET\nPATH. ONLY THE VEILED EYE\nMAY WALK IT.";
const char msg_shades[] = "SHADES DWELL BEYOND THE\nVEIL. SEE THEM, AND YOU\nCAN STRIKE THEM.";
const char msg_ruins[] = "EAST: THE EMBER TEMPLE.\nWEST: A TRIAL FOR THOSE\nWHO BEAR THE FLAME.";
const char msg_braziers[] = "COLD BRAZIERS GUARD THE\nNORTH DOOR. THEY HUNGER\nFOR FLAME.";
const char msg_mana[] = "MAGIC COSTS MANA. IT\nRETURNS SLOWLY WHILE THE\nVEIL IS DOWN.";
const char msg_boss[] = "THE GALE WARDEN GUARDS THE\nSEAL. ONLY FLAME CAN\nWOUND IT.";
const char msg_stonegate[] = "STONE SLEEPS BEHIND THE\nBRAMBLES OF THE OLD WOOD.";
const char msg_stone_entry[] = "THE STONE TEMPLE. ITS FLOOR\nHAS FALLEN AWAY IN PLACES.\nLIGHT THE WAY FORWARD.";
const char msg_tome_earth[] = "THE ART OF EARTH IS YOURS!\nYOUR STONE BREAKS CRACKED\nWALLS AND FILLS PITS.";
const char msg_seal_earth[] = "THE STONE SEAL IS BROKEN!\nTHE ART OF EARTH IS FREE,\nAND YOUR LIFE GROWS.";
const char msg_boss_serpent[] = "THE MIRE SERPENT. WATER\nYIELDS ONLY TO STONE.";
const char msg_east[] = "NORTH: THE SKY SPIRE.\nSOUTH: THE TIDE TEMPLE.";
const char msg_sky_gate[] = "THE SKY SPIRE. ITS DOOR IS\nSEALED BEHIND CRACKED STONE.";
const char msg_sky_entry[] = "WIDE CHASMS SPLIT THE SPIRE.\nNO STONE CAN FILL THEM.";
const char msg_tome_wind[] = "THE ART OF WIND IS YOURS!\nPRESS A TO DASH. YOU FLY\nOVER CHASMS AND STRIKE\nWHAT YOU PASS THROUGH.";
const char msg_seal_wind[] = "THE GALE SEAL IS BROKEN!\nTHE ART OF WIND IS FREE,\nAND YOUR LIFE GROWS.";
const char msg_boss_colossus[] = "THE STONE COLOSSUS. ONLY\nTHE WIND CAN TOPPLE IT.";
const char msg_tide_gate[] = "THE TIDE TEMPLE LIES PAST\nA CHASM NO STONE CAN FILL.";
const char msg_tide_entry[] = "WALLS OF FLAME BAR THE WAY.\nONLY THE TIDE CAN QUENCH\nTHEM.";
const char msg_tome_water[] = "THE ART OF WATER IS YOURS!\nYOUR WAVE QUENCHES WALLS\nOF FLAME.";
const char msg_seal_water[] = "THE TIDE SEAL IS BROKEN!\nTHE ART OF WATER IS FREE,\nAND YOUR LIFE GROWS.";
const char msg_boss_drake[] = "THE CINDER DRAKE. QUENCH\nITS FIRE WITH THE TIDE.";
const char msg_seals4[] = "THE FOUR SEALS ARE BROKEN.\nBENEATH THE SANCTUM, THE\nLOOM OF THE UNWEAVER OPENS\nAT LAST.";
const char msg_loom_entry[] = "THE LOOM. HERE THE UNWEAVER\nBOUND THE ARTS. YOU WILL\nNEED ALL FIVE.";
const char msg_vsigil[] = "VEIL MASTERY II! YOUR VEIL\nDRAINS HALF AS MUCH MANA.";
const char msg_boss_unweaver[] = "THE UNWEAVER HIDES BEYOND\nTHE VEIL. ITS WEAKNESS\nSHIFTS WITH ITS COLOR.";
const char msg_final[] = "THE UNWEAVER IS UNDONE!\nTHE VEIL SEAL BREAKS, AND\nTHE FIVE ARTS RETURN TO\nTHE WORLD.";
